begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','business_policies','versioned policies exist');
insert into public.organizations(id,name,slug) values('a0000000-0000-0000-0000-000000000011','Knowledge fixture','knowledge-011');
insert into auth.users(id) values('b0000000-0000-4000-8000-000000000011'),('b0000000-0000-4000-8000-000000000012');
insert into public.staff_profiles(user_id,organization_id,role) values('b0000000-0000-4000-8000-000000000011','a0000000-0000-0000-0000-000000000011','manager'),('b0000000-0000-4000-8000-000000000012','a0000000-0000-0000-0000-000000000011','staff');
insert into public.products(id,organization_id,source_name,source_url,canonical_url,name,in_stock,quality) values('c0000000-0000-4000-8000-000000000011','a0000000-0000-0000-0000-000000000011','fixture','urn:knowledge:fixture','urn:knowledge:fixture','Fixture',true,'partial');
create temporary table knowledge_fixture as select '{"kind":"return","title":"Đổi trả","body":"Liên hệ để được hướng dẫn.","startsAt":"2026-09-12T09:00:00+07:00","expiresAt":"2026-09-13T09:00:00+07:00","active":true,"scope":"all","productIds":[],"discountType":null,"discountValue":null}'::jsonb document;
grant select on knowledge_fixture to service_role;
create function pg_temp.knowledge_save(ver integer,doc jsonb default null,req uuid default gen_random_uuid(),actor uuid default 'b0000000-0000-4000-8000-000000000011') returns jsonb language sql as $$select public.save_knowledge('a0000000-0000-0000-0000-000000000011',actor,'d0000000-0000-4000-8000-000000000011',req,ver,coalesce(doc,(select document from knowledge_fixture)))$$;
set local role service_role;
select throws_ok($$select pg_temp.knowledge_save(0,null,gen_random_uuid(),'b0000000-0000-4000-8000-000000000012')$$,'42501','KNOWLEDGE_FORBIDDEN','staff mutation denied');
select lives_ok($$select pg_temp.knowledge_save(0,null,'e0000000-0000-4000-8000-000000000011')$$,'manager policy save');
select is((select version from public.business_policies where id='d0000000-0000-4000-8000-000000000011'),1,'first version');
select is((select starts_at from public.business_policies where id='d0000000-0000-4000-8000-000000000011'),'2026-09-12 02:00:00Z'::timestamptz,'offset preserved as UTC instant');
select lives_ok($$select pg_temp.knowledge_save(0,null,'e0000000-0000-4000-8000-000000000011')$$,'idempotent retry');
select is((select count(*) from public.audit_events where idempotency_key='e0000000-0000-4000-8000-000000000011'),1::bigint,'exactly one audit for retry');
select throws_ok($$select pg_temp.knowledge_save(0)$$,'40001','KNOWLEDGE_CONFLICT','stale edit conflict');
select throws_ok($$select pg_temp.knowledge_save(1,(select document||'{"body":"<script>bad</script>"}' from knowledge_fixture))$$,'22023','KNOWLEDGE_INVALID','HTML rejected at database boundary');
select throws_ok($$select pg_temp.knowledge_save(1,(select document||'{"startsAt":"2026-09-12T09:00:00"}' from knowledge_fixture))$$,'22023','KNOWLEDGE_INVALID','timestamp without explicit zone rejected');
select throws_ok($$select pg_temp.knowledge_save(1,(select document||'{"scope":"products","productIds":["c0000000-0000-4000-8000-000000000099"]}' from knowledge_fixture))$$,'42501','KNOWLEDGE_FORBIDDEN','foreign product scope denied');
select lives_ok($$select pg_temp.knowledge_save(1,(select document||'{"active":false}' from knowledge_fixture))$$,'policy soft disable');
select is((select count(*) from public.knowledge_edits where entity_id='d0000000-0000-4000-8000-000000000011'),2::bigint,'version history preserved');
select throws_ok($$select pg_temp.knowledge_save(0,(select document||'{"kind":"promotion"}' from knowledge_fixture))$$,'40001','KNOWLEDGE_CONFLICT','an existing policy ID cannot become a new promotion history');
reset role;
insert into public.promotions(id,organization_id,label,source_code,source_payload,starts_at,expires_at) values('d0000000-0000-4000-8000-000000000012','a0000000-0000-0000-0000-000000000011','Imported offer','fixture-source','{"original":true}',null,null);
insert into public.product_promotions(product_id,promotion_id) values('c0000000-0000-4000-8000-000000000011','d0000000-0000-4000-8000-000000000012');
set local role service_role;
select lives_ok($$select public.save_knowledge('a0000000-0000-0000-0000-000000000011','b0000000-0000-4000-8000-000000000011','d0000000-0000-4000-8000-000000000012',gen_random_uuid(),1,(select document||jsonb_build_object('kind','promotion','scope','products','productIds',jsonb_build_array('c0000000-0000-4000-8000-000000000011'),'startsAt',null,'expiresAt',null) from knowledge_fixture))$$,'imported promotion edited in existing truth');
select is((select source_code from public.promotions where id='d0000000-0000-4000-8000-000000000012'),'fixture-source','import source code preserved');
select is((select source_payload from public.promotions where id='d0000000-0000-4000-8000-000000000012'),'{"original":true}'::jsonb,'import source payload preserved');
reset role;
update public.promotions set starts_at=now(),expires_at=now()+interval '1 day' where id='d0000000-0000-4000-8000-000000000012';
select is((select count(*) from public.active_product_promotions where promotion_id='d0000000-0000-4000-8000-000000000012'),1::bigint,'start is inclusive');
update public.promotions set starts_at=null,expires_at=now() where id='d0000000-0000-4000-8000-000000000012';
select is((select count(*) from public.active_product_promotions where promotion_id='d0000000-0000-4000-8000-000000000012'),0::bigint,'expiry is exclusive');
update public.promotions set expires_at=null,disabled_at=now() where id='d0000000-0000-4000-8000-000000000012';
select is((select count(*) from public.active_product_promotions where promotion_id='d0000000-0000-4000-8000-000000000012'),0::bigint,'disabled promotion excluded');
set local role service_role;
select lives_ok($$select public.save_knowledge('a0000000-0000-0000-0000-000000000011','b0000000-0000-4000-8000-000000000011','d0000000-0000-4000-8000-000000000013',gen_random_uuid(),0,(select document||'{"kind":"promotion","scope":"all","productIds":[],"startsAt":null,"expiresAt":null,"discountType":"percent","discountValue":10}' from knowledge_fixture))$$,'business-wide program saves without product links');
select is((select count(*) from public.product_promotions where promotion_id='d0000000-0000-4000-8000-000000000013'),0::bigint,'global scope has no invented product links');
select is((select count(*) from public.active_product_promotions where promotion_id='d0000000-0000-4000-8000-000000000013'),1::bigint,'global offer appears in current product evidence');
select is((select scope from public.promotions where id='d0000000-0000-4000-8000-000000000012'),'products','legacy import remains product scoped');
select lives_ok($$select public.save_knowledge('a0000000-0000-0000-0000-000000000011','b0000000-0000-4000-8000-000000000011','d0000000-0000-4000-8000-000000000014',gen_random_uuid(),0,(select document||'{"kind":"promotion","scope":"all","title":"Separate offer","productIds":[],"startsAt":null,"expiresAt":null,"discountType":"percent","discountValue":20}' from knowledge_fixture))$$,'overlapping program saves separately');
select is((select count(*) from public.active_product_promotions where product_id='c0000000-0000-4000-8000-000000000011'),2::bigint,'overlapping offers are separate rows, never a combined discount');
reset role;
create function pg_temp.reject_knowledge_audit() returns trigger language plpgsql as $$begin raise exception 'knowledge_audit_failure'; end$$;
create trigger knowledge_audit_fixture before insert on public.audit_events for each row execute function pg_temp.reject_knowledge_audit();
set local role service_role;
select throws_ok($$select pg_temp.knowledge_save(2)$$,'P0001','knowledge_audit_failure','audit failure rolls back policy mutation');
select is((select version from public.business_policies where id='d0000000-0000-4000-8000-000000000011'),2,'version unchanged after audit failure');
reset role;
select * from finish();
rollback;
